309	#[derive(Debug, PartialEq, Eq, Clone)]
310	enum ParseState<'a> {
311	    /// Parsing a value done, there is no state to record.
312	    ValueDone,
313	
314	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
315	    Pos((usize, usize)),
316	
317	    /// Parsing a optional flag argument
318	    Opt(OptState<'a>),
319	}
320	
321	/// Ongoing state while an option still accepts value words.
322	#[derive(Debug, PartialEq, Eq, Clone)]
323	struct OptState<'a> {
324	    opt: &'a clap::Arg,
325	    /// Ordinal of the value word about to be consumed within this occurrence.
326	    /// A bare `--name` waiting for its first value starts at `1`; this is the
327	    /// value handed to [`ArgValueCompleter::complete_at`] as `arg_index + 1`,
328	    /// so it counts shell words and is unaffected by the value delimiter.
329	    word: usize,
330	    /// Delimiter segments already closed by earlier value words, in order.
331	    used: Vec<OsString>,
332	    /// The state was reached through a dangling value delimiter, so the next
333	    /// word is another segment of this option rather than an optional stop.
334	    open: bool,
335	    /// The value occurrence itself is complete (an attached word or a full
336	    /// delimiter set), so ordinary parsing resumes, but the option's standalone
337	    /// terminator may still arrive as the very next word. This makes the
338	    /// terminator work identically whether values arrived through `=`, a
339	    /// separate word, a short flag or an alias.
340	    closed: bool,
341	}
342	
343	impl<'a> OptState<'a> {
344	    fn new(opt: &'a clap::Arg, word: usize) -> Self {
345	        Self {
346	            opt,
347	            word,
348	            used: Vec::new(),
349	            open: false,
350	            closed: false,
351	        }
352	    }
353	}
354	
355	/// Whether an option carries several values split by a delimiter inside one
356	/// shell word *and* bounds how many such values it accepts.
357	///
358	/// An argument with the default range of one value may still pack an arbitrary
359	/// number of delimiter segments into its single word (clap's parser allows it),
360	/// and completion preserves that legacy behavior; only multi-value arguments
361	/// count segments against their range.
362	fn is_bounded_delimited(opt: &clap::Arg) -> Option<char> {
363	    let delim = opt.get_value_delimiter()?;
364	    if opt.get_num_args().expect("built").max_values() > 1 {
365	        Some(delim)
366	    } else {
367	        None
368	    }
369	}
370	
371	/// Whether a terminator glued into a value word is structurally impossible for
372	/// this option. clap rejects such a word when the option packs a bounded,
373	/// delimiter-separated set from fixed possible values (a segment like `;x` can
374	/// never name a value), while a free-form option simply takes the whole word.
375	fn glued_terminator_is_illegal(opt: &clap::Arg) -> bool {
376	    is_bounded_delimited(opt).is_some() && possible_values(opt).is_some()
377	}
378	
379	/// Split a shell value on its delimiter into its closed segments.
380	///
381	/// Returns `(segments, dangling)` where `dangling` is set when the value ends
382	/// with the delimiter: the final empty piece is the segment still being typed
383	/// rather than a closed (empty and therefore invalid) segment. Splitting works
384	/// on raw [`OsStr`] bytes, so invalid UTF-8 values are handled too.
385	fn split_delimited(value: &OsStr, delim: char) -> (Vec<&OsStr>, bool) {
386	    let mut buf = [0_u8; 4];
387	    let delim_str = delim.encode_utf8(&mut buf);
388	    let mut segments: Vec<&OsStr> = value.split(delim_str).collect();
389	    let dangling = value.contains(delim_str) && segments.last().is_some_and(|last| last.is_empty());
390	    if dangling {
391	        segments.pop();
392	    }
393	    (segments, dangling)
394	}
395	
396	/// Fold one closed value word into an option's ongoing value state.
397	///
398	/// `Ok(None)` means the occurrence is complete, `Ok(Some(state))` that another
399	/// value word is accepted and `Err(())` that the word cannot be part of a valid
400	/// command line (an empty delimiter segment or more segments than the option
401	/// accepts); the latter produces "no completion generated" rather than guesses.
402	fn consume_opt_word<'a>(
403	    prior: OptState<'a>,
404	    value: &OsStr,
405	    attached: bool,
406	) -> Result<Option<OptState<'a>>, ()> {
407	    let opt = prior.opt;
408	    let range = opt.get_num_args().expect("built");
409	    let max = range.max_values();
410	    let ordinal = prior.word;
411	    let mut used = prior.used;
412	
413	    let Some(delim) = is_bounded_delimited(opt) else {
414	        // Legacy behavior: count whole shell words against the range; whatever
415	        // is packed behind a delimiter does not extend or shorten the count.
416	        // An attached value always closes the occurrence.
417	        return Ok(if !attached && ordinal < max {
418	            Some(OptState {
419	                opt,
420	                word: ordinal + 1,
421	                used,
422	                open: false,
423	                closed: false,
424	            })
425	        } else {
426	            None
427	        });
428	    };
429	
430	    let mut buf = [0_u8; 4];
431	    let delim_str = delim.encode_utf8(&mut buf);
432	    let (segments, dangling) = split_delimited(value, delim);
433	    // Empty pieces are only invalid once a delimiter actually separates
434	    // segments; a bare empty value (`--opt=`) keeps its old tolerant behavior.
435	    if value.contains(delim_str) && segments.iter().any(|s| s.is_empty()) {
436	        return Err(());
437	    }
438	    // A closed segment must name a value the option accepts; an unknown value
439	    // cannot be part of a valid command line.
440	    if !segments_are_known(opt, &segments) {
441	        return Err(());
442	    }
443	    let closed = used.len() + segments.len();
444	    if closed > max || (closed == max && dangling) {
445	        return Err(());
446	    }
447	    used.extend(segments.iter().map(|s| s.to_os_string()));
448	
449	    // An attached value closes the occurrence unless a dangling delimiter
450	    // still accepts another segment; a space-separated word keeps accepting
451	    // values until the range is full.
452	    let accepts_more = dangling || (!attached && closed < max);
453	    if accepts_more {
454	        Ok(Some(OptState {
455	            opt,
456	            word: ordinal + 1,
457	            used,
458	            open: dangling,
459	            closed: false,
460	        }))
461	    } else if opt.get_value_terminator().is_some() {
462	        // The value occurrence is complete, but an argument with a value
463	        // terminator still accepts the standalone terminator as the very next
464	        // word, no matter whether the values arrived through `=`, a separate
465	        // word, a short flag or an alias. Keep a one-word "closed" window so
466	        // every spelling reaches the same explicit end state.
467	        Ok(Some(OptState {
468	            opt,
469	            word: ordinal + 1,
470	            used,
471	            open: false,
472	            closed: true,
473	        }))
474	    } else {
475	        Ok(None)
476	    }
477	}
478	
479	/// State after a closed `--opt=value` word: `ValueDone` when the occurrence is
480	/// complete, `Opt` when a dangling delimiter still accepts another segment.
481	/// Illegal values flag the whole command line as uncompletable.
482	fn attached_opt_state<'a>(
483	    opt: &'a clap::Arg,
484	    value: &OsStr,
485	    is_illegal: &mut bool,
486	) -> ParseState<'a> {
487	    match consume_opt_word(OptState::new(opt, 1), value, true) {
488	        Ok(Some(state)) => ParseState::Opt(state),
489	        Ok(None) => ParseState::ValueDone,
490	        Err(()) => {
491	            *is_illegal = true;
492	            ParseState::ValueDone
493	        }
494	    }
495	}
496	
497	/// Advance an ongoing option occurrence by one space-separated value word.
498	fn advance_opt_value<'a>(
499	    state: OptState<'a>,
500	    value: &OsStr,
501	    is_illegal: &mut bool,
502	) -> ParseState<'a> {
503	    match consume_opt_word(state, value, false) {
504	        Ok(Some(next)) => ParseState::Opt(next),
505	        Ok(None) => ParseState::ValueDone,
506	        Err(()) => {
507	            *is_illegal = true;
508	            ParseState::ValueDone
509	        }
510	    }
511	}
512	
513	/// Whether the whole shell word is exactly the given terminator.
514	fn word_is(terminator: &OsStr, arg: &clap_lex::ParsedArg<'_>) -> bool {
515	    arg.to_value_os() == terminator
516	}
517	
518	/// Result of analyzing the value word under the cursor for an option that
519	/// packs delimiter-separated values.
520	struct DelimCursor<'s> {
521	    /// Text of the segment currently being typed.
522	    current: &'s OsStr,
523	    /// Closed segments that precede it, in order.
524	    closed: Vec<&'s OsStr>,
525	    /// Everything in this shell word before the current segment, including the
526	    /// trailing delimiter, to re-prefix candidates with.
527	    prefix: &'s str,
528	}
529	
530	/// Whether every closed delimiter segment names a value the option accepts.
531	///
532	/// Options without a fixed value set accept anything.  A bare empty value
533	/// (`--opt=`) keeps its legacy tolerant treatment; empty segments separated
534	/// by a delimiter are rejected before this point.  A segment that is not
535	/// valid UTF-8 cannot match a possible value and is rejected, as clap's
536	/// parser would reject it.
537	fn segments_are_known(opt: &clap::Arg, segments: &[&OsStr]) -> bool {
538	    let Some(possible) = possible_values(opt) else {
539	        return true;
540	    };
541	    let ignore_case = opt.is_ignore_case_set();
542	    let possible: Vec<_> = possible.collect();
543	    segments.iter().all(|segment| {
544	        segment
545	            .to_str()
546	            .is_some_and(|s| s.is_empty() || possible.iter().any(|pv| pv.matches(s, ignore_case)))
547	    })
548	}
549	
550	/// Split the cursor value of a bounded delimiter option into the segment being
551	/// edited and its already closed prefix segments.
552	///
553	/// `Ok(None)` means the option is not a bounded delimiter option (legacy
554	/// completion applies); `Err(())` means the cursor sits at an illegal segment
555	/// position (a leading/empty segment or one past the accepted number of
556	/// values), which must not produce candidates.
557	fn cursor_delimited<'s>(
558	    opt: &clap::Arg,
559	    value: &'s OsStr,
560	    prior_segments: usize,
561	) -> Result<Option<DelimCursor<'s>>, ()> {
562	    let Some(delim) = is_bounded_delimited(opt) else {
563	        return Ok(None);
564	    };
565	    let max = opt.get_num_args().expect("built").max_values();
566	    // The cursor word being edited keeps the legacy whole-word completion when
567	    // it is not valid UTF-8; earlier closed words are still tracked by bytes.
568	    let value_str = match value.to_str() {
569	        Some(s) => s,
570	        None => return Ok(None),
571	    };
572	    let mut buf = [0_u8; 4];
573	    let delim_str = delim.encode_utf8(&mut buf);
574	
575	    let Some(pos) = value_str.rfind(delim) else {
576	        return Ok(Some(DelimCursor {
577	            current: value,
578	            closed: Vec::new(),
579	            prefix: "",
580	        }));
581	    };
582	    let (prefix, current) = value_str.split_at(pos + delim.len_utf8());
583	    let closed: Vec<&OsStr> = prefix[..prefix.len() - delim_str.len()]
584	        .split(delim)
585	        .map(OsStr::new)
586	        .collect();
587	    if closed.iter().any(|s| s.is_empty())
588	        || prior_segments + closed.len() >= max
589	        || !segments_are_known(opt, &closed)
590	    {
591	        return Err(());
592	    }
593	    Ok(Some(DelimCursor {
594	        current: OsStr::new(current),
595	        closed,
596	        prefix,
597	    }))
598	}
