600	fn complete_arg(
601	    arg: &clap_lex::ParsedArg<'_>,
602	    cmd: &clap::Command,
603	    current_dir: Option<&std::path::Path>,
604	    pos_index: usize,
605	    is_escaped: bool,
606	    state: ParseState<'_>,
607	    disabled: &HashSet<Id>,
608	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
609	    debug!(
610	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
611	        arg,
612	        cmd.get_name(),
613	        current_dir,
614	        pos_index,
615	        state
616	    );
617	    let mut completions = Vec::<CompletionCandidate>::new();
618	
619	    match state {
620	        ParseState::ValueDone => {
621	            // A closed `--name=value` word (or a short cluster carrying an
622	            // inline value, e.g. `-ovalue` / `-o=value`) is the option's value
623	            // position: only the option's own values are completed, exactly as
624	            // if the value had been written as a separate word.  The content
625	            // after `=` never takes part in subcommand, positional or
626	            // option-name completion, and the word itself is not yet part of
627	            // the conflict set.
628	            if !is_escaped {
629	                if let Some(values) = complete_inline_option_value(arg, cmd, current_dir, disabled)
630	                {
631	                    let values =
632	                        values.map_err(|()| std::io::Error::other("no completion generated"))?;
633	                    completions.extend(values);
634	                    return finalize_completions(completions);
635	                }
636	            }
637	
638	            // After `--`, only positional arguments are completed.
639	            if !is_escaped {
640	                if let Ok(value) = arg.to_value() {
641	                    completions.extend(complete_subcommand(value, cmd));
642	                }
643	            }
644	
645	            if let Some(positional) = cmd
646	                .get_positionals()
647	                .find(|p| p.get_index() == Some(pos_index))
648	            {
649	                if !disabled.contains(positional.get_id()) {
650	                    completions.extend(complete_arg_value(
651	                        arg.to_value(),
652	                        positional,
653	                        current_dir,
654	                        0,
655	                    ));
656	                }
657	            }
658	            if !is_escaped {
659	                completions.extend(complete_option(arg, cmd, current_dir, disabled));
660	            }
661	        }
662	        ParseState::Pos((_, num_arg)) => {
663	            if let Some(positional) = cmd
664	                .get_positionals()
665	                .find(|p| p.get_index() == Some(pos_index))
666	            {
667	                if !disabled.contains(positional.get_id()) {
668	                    completions.extend(complete_arg_value(
669	                        arg.to_value(),
670	                        positional,
671	                        current_dir,
672	                        num_arg.saturating_sub(1),
673	                    ));
674	                }
675	                if !is_escaped
676	                    && positional
677	                        .get_num_args()
678	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
679	                {
680	                    completions.extend(complete_option(arg, cmd, current_dir, disabled));
681	                }
682	            }
683	        }
684	        ParseState::Opt(state) => {
685	            let opt = state.opt;
686	            // A value terminator is only ever its own whole word for a bounded
687	            // delimited option.
688	            if let Some(terminator) = opt.get_value_terminator() {
689	                let min = opt.get_num_args().expect("built").min_values();
690	                let consumed_words = state.word.saturating_sub(1);
691	                let word = arg.to_value_os();
692	                let term = OsStr::new(terminator.as_str());
693	                let is_exact = word == term;
694	                let is_glued = !is_exact && word.contains(terminator.as_str());
695	                if is_glued && glued_terminator_is_illegal(opt) {
696	                    // A terminator glued onto a segment of a bounded, fixed-set
697	                    // delimiter option cannot be a value; the engine never
698	                    // guesses a split into value plus terminator. A free-form
699	                    // option takes the whole word instead.
700	                    return Err(std::io::Error::other("no completion generated"));
701	                }
702	                if is_exact {
703	                    if state.open || consumed_words < min {
704	                        // A dangling delimiter still owes its segment and the
705	                        // option still owes its minimum number of value words.
706	                        return Err(std::io::Error::other("no completion generated"));
707	                    }
708	                    // The terminator closes value taking and is never itself a
709	                    // candidate.
710	                    return finalize_completions(completions);
711	                }
712	                if state.closed {
713	                    // The value occurrence already closed (`--opt=value` or a
714	                    // full delimiter set); only the terminator word still
715	                    // belongs to it. Complete ordinary options/positionals.
716	                    return complete_arg(
717	                        arg,
718	                        cmd,
719	                        current_dir,
720	                        pos_index,
721	                        is_escaped,
722	                        ParseState::ValueDone,
723	                        disabled,
724	                    );
725	                }
726	            }
727	            if !disabled.contains(opt.get_id()) {
728	                match complete_separate_opt_value(arg.to_value(), &state, current_dir) {
729	                    Ok(values) => completions.extend(values),
730	                    // The cursor sits at an illegal segment position (an empty
731	                    // segment or one past the accepted number of values).
732	                    Err(()) => return Err(std::io::Error::other("no completion generated")),
733	                }
734	            }
735	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
736	            if state.word > min && !state.open {
737	                // Also complete this raw_arg as a positional argument, flags,
738	                // options and subcommand.  A dangling delimiter (`state.open`)
739	                // requires the next word to be this option's segment: it cannot
740	                // be a valid stop, so nothing else is offered there.
741	                completions.extend(complete_arg(
742	                    arg,
743	                    cmd,
744	                    current_dir,
745	                    pos_index,
746	                    is_escaped,
747	                    ParseState::ValueDone,
748	                    disabled,
749	                )?);
750	            }
751	        }
752	    }
753	
754	    finalize_completions(completions)
755	}
