757	/// Hide hidden candidates when visible ones exist, deduplicate by id and sort
758	/// into the presentation order shared by every completion source.
759	fn finalize_completions(
760	    mut completions: Vec<CompletionCandidate>,
761	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
762	    if completions.iter().any(|a| !a.is_hide_set()) {
763	        completions.retain(|a| !a.is_hide_set());
764	    }
765	    let mut seen_ids = HashSet::new();
766	    completions.retain(move |a| {
767	        if let Some(id) = a.get_id().cloned() {
768	            seen_ids.insert(id)
769	        } else {
770	            true
771	        }
772	    });
773	    // Different sources (a subcommand and a positional value, an option alias
774	    // and a directory entry, ...) can propose the same literal insertion text
775	    // under different ids; only the first is kept.  Retaining by first
776	    // occurrence keeps the presentation order untouched by aliases or
777	    // duplicate directory entries.
778	    let mut seen_values = HashSet::new();
779	    completions.retain(move |a| seen_values.insert(a.get_value().to_os_string()));
780	
781	    let mut tags = Vec::new();
782	    for candidate in &completions {
783	        let tag = candidate.get_tag().cloned();
784	        if !tags.contains(&tag) {
785	            tags.push(tag);
786	        }
787	    }
788	    completions.sort_by_key(|c| {
789	        (
790	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
791	            c.get_display_order(),
792	        )
793	    });
794	
795	    Ok(completions)
796	}
