880	/// Complete the inline value carried by the cursor's option word.
881	///
882	/// This covers `--name=value` as well as short clusters with an attached
883	/// value, e.g. `-ovalue` and `-o=value` (including leading flags, `-abovalue`).
884	/// It returns the option's value candidates, re-prefixed with the exact
885	/// option spelling, when the cursor is inside such a value.  The whole word is
886	/// consumed by its option: nothing after `=` or past the taking flag takes
887	/// part in option-name, subcommand or positional completion, and the word is
888	/// not yet part of the conflict set.
889	///
890	/// A bare `--name`/`-o` whose value is still a separate word completes
891	/// normally, as does an unknown long name, a recognized option that takes no
892	/// value and anything else that cannot be recognized: `None` preserves the
893	/// existing failure semantics rather than guessing a split.
894	///
895	/// `Some(Err(()))` means the recognized word is an illegal value position for
896	/// a bounded delimiter option (an empty segment or a segment past the accepted
897	/// number of values) and must yield "no completion generated".
898	fn complete_inline_option_value(
899	    arg: &clap_lex::ParsedArg<'_>,
900	    cmd: &clap::Command,
901	    current_dir: Option<&std::path::Path>,
902	    disabled: &HashSet<Id>,
903	) -> Option<Result<Vec<CompletionCandidate>, ()>> {
904	    if let Some((flag, value)) = arg.to_long() {
905	        let flag = flag.ok()?;
906	        // A bare `--name` has no attached value and is completed as an option name.
907	        let value = value?;
908	        let opt = cmd.get_arguments().find(|a| {
909	            a.get_long_and_visible_aliases()
910	                .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
911	        })?;
912	        if !opt.get_num_args().expect("built").takes_values() {
913	            return None;
914	        }
915	        if disabled.contains(opt.get_id()) {
916	            return Some(Ok(Vec::new()));
917	        }
918	        let prefix = format!("--{flag}=");
919	        return Some(
920	            complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
921	                values
922	                    .into_iter()
923	                    .map(|comp| comp.add_prefix(&prefix))
924	                    .collect()
925	            }),
926	        );
927	    }
928	
929	    let short = arg.to_short()?;
930	    if short.is_negative_number() {
931	        return None;
932	    }
933	    let (leading_flags, opt, mut value_flags, _) = parse_shortflags(cmd, short);
934	    let opt = opt?;
935	
936	    // Detect an attached value: once the cluster reaches its value-taking
937	    // flag, everything left is the value, optionally introduced by `=`.  With
938	    // no remainder and no `=` (`-o`), the word is left to the regular option
939	    // completion, which already offers inline values.
940	    let mut peek = value_flags.clone();
941	    let has_equal = matches!(peek.next_flag(), Some(Ok('=')));
942	    if !has_equal && value_flags.is_empty() {
943	        return None;
944	    }
945	    if has_equal {
946	        // Consume the `=` so the remainder is the bare value (possibly empty
947	        // for `-o=`), matching the space-separated empty-value position.
948	        value_flags.next_flag();
949	    }
950	    if disabled.contains(opt.get_id()) {
951	        return Some(Ok(Vec::new()));
952	    }
953	    let value = value_flags.next_value_os().unwrap_or(OsStr::new(""));
954	    let sep = if has_equal { "=" } else { "" };
955	    let prefix = format!("-{leading_flags}{sep}");
956	    Some(
957	        complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
958	            values
959	                .into_iter()
960	                .map(|comp| comp.add_prefix(&prefix))
961	                .collect()
962	        }),
963	    )
964	}
