966	fn complete_option(
967	    arg: &clap_lex::ParsedArg<'_>,
968	    cmd: &clap::Command,
969	    current_dir: Option<&std::path::Path>,
970	    disabled: &HashSet<Id>,
971	) -> Vec<CompletionCandidate> {
972	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
973	    let mut completions = Vec::<CompletionCandidate>::new();
974	    if arg.is_empty() {
975	        completions.extend(longs_and_visible_aliases(cmd, disabled));
976	        completions.extend(hidden_longs_aliases(cmd, disabled));
977	
978	        let dash_or_arg = if arg.is_empty() {
979	            "-".into()
980	        } else {
981	            arg.to_value_os().to_string_lossy()
982	        };
983	        completions.extend(
984	            shorts_and_visible_aliases(cmd, disabled)
985	                .into_iter()
986	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
987	        );
988	    } else if arg.is_stdio() {
989	        // HACK: Assuming knowledge of is_stdio
990	        let dash_or_arg = if arg.is_empty() {
991	            "-".into()
992	        } else {
993	            arg.to_value_os().to_string_lossy()
994	        };
995	        completions.extend(
996	            shorts_and_visible_aliases(cmd, disabled)
997	                .into_iter()
998	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
999	        );
1000	
1001	        completions.extend(longs_and_visible_aliases(cmd, disabled));
1002	        completions.extend(hidden_longs_aliases(cmd, disabled));
1003	    } else if arg.is_escape() {
1004	        // HACK: Assuming knowledge of is_escape
1005	        completions.extend(longs_and_visible_aliases(cmd, disabled));
1006	        completions.extend(hidden_longs_aliases(cmd, disabled));
1007	    } else if let Some((flag, value)) = arg.to_long() {
1008	        if let Ok(flag) = flag {
1009	            if let Some(value) = value {
1010	                let opt = cmd.get_arguments().find(|a| {
1011	                    a.get_long_and_visible_aliases()
1012	                        .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
1013	                });
1014	                if let Some(arg) = opt {
1015	                    if !disabled.contains(arg.get_id()) {
1016	                        if let Ok(values) =
1017	                            complete_segment_value(value, arg, 0, &[], 0, current_dir)
1018	                        {
1019	                            completions.extend(
1020	                                values
1021	                                    .into_iter()
1022	                                    .map(|comp| comp.add_prefix(format!("--{flag}="))),
1023	                            );
1024	                        }
1025	                    }
1026	                }
1027	            } else {
1028	                completions.extend(
1029	                    longs_and_visible_aliases(cmd, disabled)
1030	                        .into_iter()
1031	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
1032	                );
1033	                completions.extend(
1034	                    hidden_longs_aliases(cmd, disabled)
1035	                        .into_iter()
1036	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
1037	                );
1038	            }
1039	        }
1040	    } else if let Some(short) = arg.to_short() {
1041	        if !short.is_negative_number() {
1042	            // Find the first takes_values option.
1043	            let (leading_flags, takes_value_opt, mut short, _) = parse_shortflags(cmd, short);
1044	
1045	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
1046	            if let Some(opt) = takes_value_opt {
1047	                if !disabled.contains(opt.get_id()) {
1048	                    let mut peek_short = short.clone();
1049	                    let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
1050	                        short.next_flag();
1051	                        true
1052	                    } else {
1053	                        false
1054	                    };
1055	
1056	                    let value = short.next_value_os().unwrap_or(OsStr::new(""));
1057	                    if let Ok(values) = complete_segment_value(value, opt, 0, &[], 0, current_dir) {
1058	                        completions.extend(values.into_iter().map(|comp| {
1059	                            let sep = if has_equal { "=" } else { "" };
1060	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
1061	                        }));
1062	                    }
1063	                }
1064	            } else {
1065	                completions.extend(
1066	                    shorts_and_visible_aliases(cmd, disabled)
1067	                        .into_iter()
1068	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
1069	                );
1070	            }
1071	        }
1072	    }
1073	    debug!("complete_option: completions={completions:?}");
1074	    completions
1075	}
