1077	fn complete_arg_value(
1078	    value: Result<&str, &OsStr>,
1079	    arg: &clap::Arg,
1080	    current_dir: Option<&std::path::Path>,
1081	    arg_index: usize,
1082	) -> Vec<CompletionCandidate> {
1083	    let mut values = Vec::new();
1084	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
1085	
1086	    let (prefix, value) =
1087	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
1088	
1089	    let value_os = match value {
1090	        Ok(value) => OsStr::new(value),
1091	        Err(value_os) => value_os,
1092	    };
1093	
1094	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
1095	        values.extend(completer.complete_at(arg_index, value_os));
1096	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
1097	        values.extend(complete_value_candidates(
1098	            value_os,
1099	            completer.value_candidates(),
1100	        ));
1101	    } else if let Some(possible_values) = possible_values(arg) {
1102	        if let Ok(value) = value {
1103	            values.extend(complete_candidates_str(
1104	                value,
1105	                possible_value_candidates(possible_values),
1106	            ));
1107	        }
1108	    } else {
1109	        match arg.get_value_hint() {
1110	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
1111	                // Should not complete
1112	            }
1113	            clap::ValueHint::AnyPath => {
1114	                values.extend(complete_path(value_os, current_dir, &|_| true));
1115	            }
1116	            clap::ValueHint::FilePath => {
1117	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
1118	            }
1119	            clap::ValueHint::DirPath => {
1120	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
1121	            }
1122	            clap::ValueHint::ExecutablePath => {
1123	                use is_executable::IsExecutable;
1124	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
1125	            }
1126	            clap::ValueHint::CommandName
1127	            | clap::ValueHint::CommandString
1128	            | clap::ValueHint::CommandWithArguments
1129	            | clap::ValueHint::Username
1130	            | clap::ValueHint::Hostname
1131	            | clap::ValueHint::Url
1132	            | clap::ValueHint::EmailAddress => {
1133	                // No completion implementation
1134	            }
1135	            _ => {
1136	                // Safe-ish fallback
1137	                values.extend(complete_path(value_os, current_dir, &|_| true));
1138	            }
1139	        }
1140	
1141	        values.sort();
1142	    }
1143	
1144	    if let Some(prefix) = prefix {
1145	        values = values
1146	            .into_iter()
1147	            .map(|comp| comp.add_prefix(prefix))
1148	            .collect();
1149	    }
1150	    values = values
1151	        .into_iter()
1152	        .map(|comp| {
1153	            if comp.get_tag().is_some() {
1154	                comp
1155	            } else {
1156	                comp.tag(Some(arg.to_string().into()))
1157	            }
1158	        })
1159	        .collect();
1160	
1161	    debug!("complete_arg_value: values={values:?}");
1162	    values
1163	}
