1165	fn rsplit_delimiter<'s, 'o>(
1166	    value: Result<&'s str, &'o OsStr>,
1167	    delimiter: Option<char>,
1168	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
1169	    let delimiter = delimiter?;
1170	    let value = value.ok()?;
1171	    let pos = value.rfind(delimiter)?;
1172	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
1173	    Some((Some(prefix), Ok(value)))
1174	}
