1206	/// Resolve a closed word to the subcommand it selects on this level.
1207	///
1208	/// This mirrors clap's parser: an exact name or alias always wins (so a
1209	/// positional value that merely shares a prefix, e.g. `remote`, cannot shadow a
1210	/// subcommand of the same name); otherwise, when subcommand inference is
1211	/// enabled, a unique name-or-alias prefix selects that subcommand. A prefix
1212	/// shared by several subcommands resolves to nothing here, just as clap
1213	/// rejects such a word rather than choosing a branch; the caller then treats
1214	/// it as an ordinary positional value.
1215	fn select_subcommand<'c>(cmd: &'c clap::Command, value: &str) -> Option<&'c clap::Command> {
1216	    if let Some(subcommand) = cmd.find_subcommand(value) {
1217	        return Some(subcommand);
1218	    }
1219	    if cmd.is_infer_subcommands_set() {
1220	        let mut matches = cmd.get_subcommands().filter(|subcommand| {
1221	            subcommand.get_name().starts_with(value)
1222	                || subcommand
1223	                    .get_all_aliases()
1224	                    .any(|alias| alias.starts_with(value))
1225	        });
1226	        let first = matches.next()?;
1227	        if matches.next().is_none() {
1228	            return Some(first);
1229	        }
1230	    }
1231	    None
1232	}
1233	
1234	/// Whether a closed (already submitted) word can occupy the positional slot at
1235	/// `pos_index`, mirroring clap's parser.
1236	///
1237	/// A positional without a fixed value set (a free-form parser, a path hint or
1238	/// a custom completer) accepts every word. A positional backed by possible
1239	/// values accepts only one of them (by name or alias, honoring
1240	/// `ignore_case`), splitting a bounded delimiter word into its segments just
1241	/// like an option value. With no positional slot left, an external subcommand
1242	/// command swallows the word; otherwise clap rejects the line.
1243	fn closed_positional_is_accepted(cmd: &clap::Command, pos_index: usize, word: &OsStr) -> bool {
1244	    let Some(positional) = cmd
1245	        .get_positionals()
1246	        .find(|p| p.get_index() == Some(pos_index))
1247	    else {
1248	        // No slot remains: an external subcommand accepts any trailing word,
1249	        // anything else is an unrecognized subcommand/argument.
1250	        return cmd.is_allow_external_subcommands_set();
1251	    };
1252	
1253	    let Some(possible) = possible_values(positional) else {
1254	        return true;
1255	    };
1256	    let ignore_case = positional.is_ignore_case_set();
1257	    let possible: Vec<_> = possible.collect();
1258	
1259	    let segments: Vec<&OsStr> = match is_bounded_delimited(positional) {
1260	        Some(delim) => {
1261	            let (segments, _dangling) = split_delimited(word, delim);
1262	            segments
1263	        }
1264	        None => vec![word],
1265	    };
1266	    segments.iter().all(|segment| {
1267	        segment
1268	            .to_str()
1269	            .is_some_and(|s| possible.iter().any(|pv| pv.matches(s, ignore_case)))
1270	    })
1271	}
1272	
1273	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
1274	    debug!(
1275	        "complete_subcommand: cmd={:?}, value={:?}",
1276	        cmd.get_name(),
1277	        value
1278	    );
1279	
1280	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
1281	        .into_iter()
1282	        .filter(|x| x.get_value().starts_with(value))
1283	        .collect();
1284	    if cmd.is_allow_external_subcommands_set() {
1285	        let external_completer = cmd.get::<SubcommandCandidates>();
1286	        if let Some(completer) = external_completer {
1287	            scs.extend(complete_value_candidates_str(
1288	                value,
1289	                completer.value_candidates(),
1290	            ));
1291	        }
1292	    }
1293	
1294	    // `subcommands` lists the canonical name before each of its aliases; drop
1295	    // aliases of a subcommand whose canonical name is still offered. This must
1296	    // happen before the alphabetical sort, or a short alias (`r` for `run`,
1297	    // `rem` for `remote`) would sort ahead of the canonical name and survive
1298	    // the later by-id de-duplication instead of it.
1299	    let mut seen_ids = HashSet::new();
1300	    scs.retain(|candidate| {
1301	        candidate
1302	            .get_id()
1303	            .cloned()
1304	            .map(|id| seen_ids.insert(id))
1305	            .unwrap_or(true)
1306	    });
1307	
1308	    scs.sort();
1309	    scs.dedup();
1310	    scs
1311	}
