1439	/// Parse the short flags and find the first `takes_values` option.
1440	///
1441	/// The returned bool is `true` only when every scanned cluster member was a
1442	/// recognized option. Anything after the first value-taking option is the
1443	/// option's value and therefore not scanned; invalid UTF-8 and unknown short
1444	/// characters make the result `false`.
1445	fn parse_shortflags<'c, 's>(
1446	    cmd: &'c clap::Command,
1447	    mut short: clap_lex::ShortFlags<'s>,
1448	) -> (
1449	    String,
1450	    Option<&'c clap::Arg>,
1451	    clap_lex::ShortFlags<'s>,
1452	    bool,
1453	) {
1454	    let takes_value_opt;
1455	    let mut leading_flags = String::new();
1456	    let mut cluster_valid = true;
1457	    // Find the first takes_values option.
1458	    loop {
1459	        match short.next_flag() {
1460	            Some(Ok(opt)) => {
1461	                leading_flags.push(opt);
1462	                let found = cmd.get_arguments().find(|a| {
1463	                    let shorts = a.get_short_and_visible_aliases();
1464	                    let is_find = shorts.map(|v| {
1465	                        let mut iter = v.into_iter();
1466	                        let c = iter.find(|c| *c == opt);
1467	                        c.is_some()
1468	                    });
1469	                    is_find.unwrap_or(false)
1470	                });
1471	                if let Some(opt) = found {
1472	                    if opt.get_num_args().expect("built").takes_values() {
1473	                        takes_value_opt = Some(opt);
1474	                        break;
1475	                    }
1476	                } else {
1477	                    cluster_valid = false;
1478	                }
1479	            }
1480	            Some(Err(_)) => {
1481	                cluster_valid = false;
1482	                takes_value_opt = None;
1483	                break;
1484	            }
1485	            None => {
1486	                takes_value_opt = None;
1487	                break;
1488	            }
1489	        }
1490	    }
1491	
1492	    (leading_flags, takes_value_opt, short, cluster_valid)
1493	}
