1495	/// Parse the positional arguments. Return the new state and the new positional index.
1496	fn parse_positional<'a>(
1497	    cmd: &clap::Command,
1498	    pos_index: usize,
1499	    is_escaped: bool,
1500	    state: ParseState<'a>,
1501	) -> (ParseState<'a>, usize) {
1502	    let pos_arg = cmd
1503	        .get_positionals()
1504	        .find(|p| p.get_index() == Some(pos_index));
1505	    let num_args = pos_arg
1506	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1507	        .unwrap_or(1);
1508	
1509	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1510	        if num_args > 1 {
1511	            (ParseState::Pos((pos_index, 1)), pos_index)
1512	        } else {
1513	            if is_escaped {
1514	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1515	            } else {
1516	                (ParseState::ValueDone, pos_index + 1)
1517	            }
1518	        }
1519	    };
1520	    match state {
1521	        ParseState::ValueDone => {
1522	            update_state_with_new_positional(pos_index)
1523	        },
1524	        ParseState::Pos((prev_pos_index, num_arg)) => {
1525	            if prev_pos_index == pos_index {
1526	                if num_arg + 1 < num_args {
1527	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1528	                } else {
1529	                    if is_escaped {
1530	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1531	                    } else {
1532	                        (ParseState::ValueDone, pos_index + 1)
1533	                    }
1534	                }
1535	            } else {
1536	                update_state_with_new_positional(pos_index)
1537	            }
1538	        }
1539	        ParseState::Opt(..) => unreachable!(
1540	            "This branch won't be hit,
1541	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1542	        ),
1543	    }
1544	}
