use std::fs;

fn tool() -> clap::Command {
    clap::Command::new("tool")
        .arg(
            clap::Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("number")
                .short('n')
                .long("number")
                .value_parser(["-3", "-2", "-1", "0", "1", "2", "3"]),
        )
        .arg(
            clap::Arg::new("mode")
                .long("mode")
                .value_parser(["fast", "safe"]),
        )
        .arg(clap::Arg::new("path").value_hint(clap::ValueHint::DirPath))
}

fn run(input: &str, dir: Option<&std::path::Path>) -> String {
    let mut args = vec![std::ffi::OsString::from("tool")];
    let arg_index;
    let (prior, _) = input.split_once("[TAB]").unwrap();
    args.extend(prior.split_whitespace().map(From::from));
    if prior.ends_with(char::is_whitespace) {
        args.push(std::ffi::OsString::default());
    }
    arg_index = args.len() - 1;
    match clap_complete::engine::complete(&mut tool(), args, arg_index, dir) {
        Ok(cs) => cs
            .into_iter()
            .map(|c| c.get_value().to_str().unwrap().to_owned())
            .collect::<Vec<_>>()
            .join(","),
        Err(e) => format!("ERR:{e}"),
