#!/usr/bin/env python3
import os
import pathlib
import subprocess
import sys

# Coverage: root empty word lists visible subcommands and target values; exact,
# unique-prefix, and alias words select one parsing layer; ambiguous committed
# prefixes and unknown/glued/overlong words fail; -- restricts candidates to
# current-layer positionals/directories; repeated spellings are equivalent.
# These assertions reject parent leakage, arbitrary branch choice, option leakage,
# hidden candidates, and stale inferred state.

case = sys.argv[1] if len(sys.argv) > 1 else "all"
if case not in ("all", "core", "errors"):
    print("usage: dynamic_layer.py [core|errors]", file=sys.stderr)
    raise SystemExit(2)
root = pathlib.Path(__file__).resolve().parents[1]
tests = root / "clap_complete" / "tests"
name = f"acceptance_layer_{os.getpid()}"
path = tests / f"{name}.rs"
source = r'''
use clap::{Arg, Command, ValueHint};
use clap_complete::engine::complete;
use std::ffi::OsString;
use std::fs;

fn command() -> Command {
    Command::new("tool").infer_subcommands(true)
        .arg(Arg::new("target").value_parser(["local", "remote"]))
        .arg(Arg::new("secret").long("secret").hide(true))
        .subcommand(Command::new("run").visible_alias("r")
            .arg(Arg::new("profile").long("profile"))
            .arg(Arg::new("dir").value_hint(ValueHint::DirPath)))
        .subcommand(Command::new("remote").visible_alias("rem")
            .arg(Arg::new("url").long("url")))
        .subcommand(Command::new("reset"))
        .subcommand(Command::new("hidden-cmd").hide(true))
}
fn values(mut c: Command, words: &[&str], index: usize, dir: Option<&std::path::Path>) -> Result<Vec<String>, String> {
    let args: Vec<OsString> = words.iter().map(|s| OsString::from(*s)).collect();
    complete(&mut c, args, index, dir)
        .map(|xs| xs.into_iter().map(|x| x.get_value().to_string_lossy().into_owned()).collect())
        .map_err(|e| e.to_string())
}
fn main() {
    let d = std::env::temp_dir().join(format!("clap-layer-{}", std::process::id()));
    fs::create_dir_all(d.join("a_dir")).unwrap();
    fs::create_dir_all(d.join("b_dir")).unwrap();
    let mode = std::env::var("LAYER_CASE").unwrap_or_else(|_| "all".into());
    if mode != "errors" {
        let cases = vec![
            ("root-empty", values(command(), &["tool", ""], 1, Some(&d)), vec!["run","remote","reset","local"]),
            ("run-prefix", values(command(), &["tool","ru",""], 2, Some(&d)), vec!["--profile"]),
            ("run-alias", values(command(), &["tool","r",""], 2, Some(&d)), vec!["--profile"]),
            ("remote-exact", values(command(), &["tool","remote",""], 2, None), vec!["--url"]),
            ("remote-alias", values(command(), &["tool","rem",""], 2, None), vec!["--url"]),
            ("local-root", values(command(), &["tool","local",""], 2, None), vec!["run","remote","reset","--help"]),
            ("escape-root", values(command(), &["tool","--",""], 2, None), vec!["local","remote"]),
            ("escape-run", values(command(), &["tool","run","--",""], 3, Some(&d)), vec![".","a_dir/","b_dir/"]),
        ];
        for (name, got, required) in cases {
            println!("CASE {name}: {got:?}");
            let mut actual = got.unwrap_or_else(|e| panic!("{name} returned error: {e}"));
            actual.sort();
            for want in required { assert!(actual.iter().any(|x| x == want), "{name} missing {want:?}: {actual:?}"); }
            assert!(!actual.iter().any(|x| x == "secret" || x == "hidden-cmd"), "hidden candidate leaked: {actual:?}");
        }
        let a = values(command(), &["tool","run","--pr"], 2, None).unwrap();
        let b = values(command(), &["tool","r","--pr"], 2, None).unwrap();
        let c = values(command(), &["tool","ru","--pr"], 2, None).unwrap();
        println!("CASE equivalent: {a:?} {b:?} {c:?}");
        assert_eq!(a, b); assert_eq!(b, c);
    }
    if mode != "core" {
        for (name, words, index) in [
            ("ambiguous-re", vec!["tool","re",""], 2usize),
            ("unknown-option", vec!["tool","--bogus",""], 2),
            ("glued", vec!["tool","toolruX",""], 2),
            ("overlong", vec!["tool","runn",""], 2),
            ("reset-extra", vec!["tool","reset","x",""], 3),
        ] {
            let got = values(command(), &words, index, None);
            println!("CASE {name}: {got:?}");
            assert!(got.is_err(), "{name} unexpectedly succeeded: {got:?}");
        }
    }
    fs::remove_dir_all(d).unwrap();
}
'''
path.write_text(source)
env = os.environ.copy()
env["LAYER_CASE"] = case
try:
    result = subprocess.run(["cargo", "test", "--offline", "-p", "clap_complete", "--features", "unstable-dynamic", "--test", name, "--", "--nocapture"], cwd=root, env=env, text=True, capture_output=True)
    sys.stdout.write(result.stdout)
    sys.stderr.write(result.stderr)
    raise SystemExit(result.returncode)
finally:
    try:
        path.unlink()
    except FileNotFoundError:
        pass

#!/usr/bin/env python3
# 覆盖表：独立终止符结束取值 -> case_long_terminator/case_short_terminator/case_positional_terminator -> 后续空词不含原参数值；终止符本身 -> same cases 的 target assertions -> 候选全集排除 ";"；终止前取值 -> case_before_terminator -> 仍补 a,b；短选项/位置参数/不回退 -> corresponding cases -> 完整候选与顺序；别名、value_delimiter、--、排序、去重、隐藏 -> preservation cases -> 保持既有行为；arg_index 无词 -> case_missing_index -> Err("no completion generated")。反例自检见各 CASES 注释。
import json
import os
import shutil
import subprocess
import sys
import tempfile

WORKSPACE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

CASES = [
    # 未排除终止符或仍回退到原参数值的实现会在 exact equality 失败。
    ("long_terminator", ["app", "--term", "a", ";", ""], 4, ["x", "y", "--term", "--help"]),
    ("short_terminator", ["app", "-t", "a", ";", ""], 4, ["x", "y", "-t", "--help"]),
    ("positional_terminator", ["app", "a", ";", ""], 3, ["go", "help", "x", "y", "--flag", "--help"]),
    # 只在首个匹配处提前结束取值的实现会让第二值仍得到 a,b。
    ("before_terminator", ["app", "--term", "a", ""], 3, ["a", "b", "x", "y", "--term", "--help"]),
    # 把 ";" 当普通值或前缀候选的实现会得到非空结果。
    ("target_is_terminator", ["app", "--term", "a", ";"], 3, []),
    ("pos_target_is_terminator", ["app", "a", ";"], 2, []),
    # 终止后再次遇到 -- 会把状态回退到原参数，从而混入 a,b。
    ("escape_after_terminator", ["app", "--term", "a", ";", "--", ""], 5, ["x", "y"]),
    # 别名字面与隐藏项处理若被终止符路径绕过，集合或排序会变化。
    ("alias_and_hidden", ["app", "--alias", "a", ";", ""], 4, ["x", "y", "--term", "--help"]),
]

DELIMITED = (["app", "--delim", "a,b", ""], 3, ["a,a", "a,b", "--delim", "--help"])
SORT_DEDUP = (["app", "zz", ""], 2, ["aa", "mm", "zz", "--flag", "--help"])
MISSING = (["app", "--term", "a", ";"], 4)

HARNESS = r'''use std::ffi::OsString;
use std::path::PathBuf;
use clap::{Arg, ArgAction, Command};
use clap_complete::engine::{complete, CompletionCandidate};

fn encode(v: &[CompletionCandidate]) -> String {
    let values: Vec<String> = v.iter().map(|c| c.get_value().to_string_lossy().into_owned()).collect();
    serde_json::to_string(&values).unwrap()
}
fn run(name: &str, args: &[&str], index: usize) {
    let mut cmd = Command::new("app")
        .arg(Arg::new("term").long("term").short('t').alias("alias").num_args(1..).value_terminator(";").value_parser(["a", "b"]).hide(true))
        .arg(Arg::new("delim").long("delim").num_args(1..).value_delimiter(',').value_terminator(";").value_parser(["a", "b"]))
        .arg(Arg::new("first").num_args(1..).value_terminator(";").value_parser(["a", "b"]).required(true))
        .arg(Arg::new("pos").value_parser(["x", "y"]))
        .arg(Arg::new("flag").long("flag").short('f').action(ArgAction::SetTrue))
        .subcommand(Command::new("go"));
    let words: Vec<OsString> = args.iter().map(OsString::from).collect();
    match complete(&mut cmd, words, index, Some(&PathBuf::from("."))) {
        Ok(v) => println!("CASE {} OK {}", name, encode(&v)),
        Err(e) => println!("CASE {} ERR {}", name, e),
    }
}
fn main() {
''' + "\n".join(
    f'    run({json.dumps(n)}, &[{", ".join(json.dumps(x) for x in args)}], {idx});'
    for n, args, idx, _ in CASES + [tuple(x) for x in [DELIMITED, SORT_DEDUP]] + [tuple(MISSING)]
) + r'''
}
'''

def fail(message):
    print("PRODUCT_ASSERTION_FAILED: " + message, file=sys.stderr)
    raise SystemExit(1)

def main():
    temp = tempfile.mkdtemp(prefix="clap-complete-acceptance-")
    try:
        src = os.path.join(temp, "src")
        os.mkdir(src)
        with open(os.path.join(temp, "Cargo.toml"), "w", encoding="utf-8") as f:
            f.write('[package]\nname="acceptance-harness"\nversion="0.0.0"\nedition="2021"\n[dependencies]\nclap={path="' + WORKSPACE.replace("\\", "\\\\") + '"}\nclap_complete={path="' + WORKSPACE.replace("\\", "\\\\") + '/clap_complete"}\nserde_json="1"\n')
        with open(os.path.join(src, "main.rs"), "w", encoding="utf-8") as f:
            f.write(HARNESS)
        env = os.environ.copy()
        env["CARGO_TARGET_DIR"] = os.path.join(temp, "target")
        proc = subprocess.run(["cargo", "run", "--quiet", "--offline", "--manifest-path", os.path.join(temp, "Cargo.toml")], env=env, text=True, capture_output=True)
        sys.stdout.write(proc.stdout)
        sys.stderr.write(proc.stderr)
        if proc.returncode != 0:
            print("ADAPTATION_OR_ENV_FAILURE: harness build/run failed with exit %d" % proc.returncode, file=sys.stderr)
            raise SystemExit(2)
        observed = {}
        for line in proc.stdout.splitlines():
            if not line.startswith("CASE "):
                continue
            parts = line.split(" ", 3)
            if len(parts) < 4:
                fail("malformed harness output: " + line)
            observed[parts[1]] = (parts[2], parts[3])
        expected = {n: v for n, _, _, v in CASES}
        expected["delimited"] = list(DELIMITED[2])
        expected["sort_dedup"] = list(SORT_DEDUP[2])
        expected["missing_index"] = ("ERR", json.dumps("no completion generated"))
        for name, want in expected.items():
            got = observed.get(name)
            if got is None:
                fail("missing result for " + name)
            if name == "missing_index":
                if got != want:
                    fail("arg_index=4 must Err(io::Error::other(\"no completion generated\")), got " + repr(got))
            else:
                try:
                    values = json.loads(got[1])
                except Exception as exc:
                    fail("invalid candidate encoding for " + name + ": " + str(exc))
                if got[0] != "OK" or values != want:
                    fail(name + " expected exact ordered candidates " + repr(want) + ", got " + repr(got))
        print("all value_terminator contract checks passed")
    finally:
        shutil.rmtree(temp, ignore_errors=True)

