fn suggest_delimited_multi_value_conflict_suppression() {
    fn command() -> Command {
        Command::new("fmt")
            .arg(
                clap::Arg::new("format")
                    .long("format")
                    .num_args(1..=2)
                    .value_parser(["json", "yaml"])
