        if state.open && !is_escaped && !opt_allows_hyphen(&current_state, &arg) {
            let is_option_word = arg.is_escape()
                || arg.to_long().is_some()
                || arg
                    .to_short()
                    .is_some_and(|short| !short.is_negative_number());
