563	/// edited and its already closed prefix segments.
564	///
565	/// `Ok(None)` means the option is not a bounded delimiter option (legacy
566	/// completion applies); `Err(())` means the cursor sits at an illegal segment
567	/// position (a leading/empty segment or one past the accepted number of
568	/// values), which must not produce candidates.
569	fn cursor_delimited<'s>(
570	    opt: &clap::Arg,
571	    value: &'s OsStr,
572	    prior_segments: usize,
573	) -> Result<Option<DelimCursor<'s>>, ()> {
574	    let Some(delim) = is_bounded_delimited(opt) else {
575	        return Ok(None);
576	    };
577	    let max = opt.get_num_args().expect("built").max_values();
578	    // The cursor word being edited keeps the legacy whole-word completion when
579	    // it is not valid UTF-8; earlier closed words are still tracked by bytes.
580	    let value_str = match value.to_str() {
581	        Some(s) => s,
582	        None => return Ok(None),
583	    };
584	    let mut buf = [0_u8; 4];
585	    let delim_str = delim.encode_utf8(&mut buf);
586	
587	    let Some(pos) = value_str.rfind(delim) else {
588	        return Ok(Some(DelimCursor {
589	            current: value,
590	            closed: Vec::new(),
591	            prefix: "",
592	        }));
593	    };
