#![cfg(feature = "unstable-dynamic")]

use std::fs;

fn tool() -> clap::Command {
    clap::Command::new("tool")
        .arg(
            clap::Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("number")
                .short('n')
                .long("number")
                .value_parser(["-3", "-2", "-1", "0", "1", "2", "3"]),
        )
        .arg(
            clap::Arg::new("mode")
                .long("mode")
                .value_parser(["fast", "safe"]),
        )
        .arg(clap::Arg::new("path").value_hint(clap::ValueHint::DirPath))
}

fn run(input: &str, dir: Option<&std::path::Path>) -> String {
    let mut args = vec![std::ffi::OsString::from("tool")];
    let (prior, _) = input.split_once("[TAB]").unwrap();
    args.extend(prior.split_whitespace().map(From::from));
    if prior.ends_with(char::is_whitespace) {
        args.push(std::ffi::OsString::default());
    }
    let arg_index = args.len() - 1;
    match clap_complete::engine::complete(&mut tool(), args, arg_index, dir) {
        Ok(cs) => cs
            .into_iter()
            .map(|c| c.get_value().to_str().unwrap().to_owned())
            .collect::<Vec<_>>()
            .join(","),
        Err(e) => format!("ERR:{e}"),
    }
}

#[test]
fn probe_all() {
    let testdir = snapbox::dir::DirRoot::mutable_temp().unwrap();
    let path = testdir.path().unwrap();
    fs::create_dir_all(path.join("a_dir/nested")).unwrap();
    fs::create_dir_all(path.join("b_dir")).unwrap();
    fs::write(path.join("a_file"), "").unwrap();

    let cases = [
        (" [TAB]", None),
        ("- [TAB]", None),
        ("-v [TAB]", None),
        ("-v -[TAB]", None),
        ("-vn[TAB]", None),
        ("-n [TAB]", None),
        ("-n-[TAB]", None),
        ("-n-3 [TAB]", None),
        ("--number=-3 [TAB]", None),
        ("--number -3 [TAB]", None),
        ("-vn-3 [TAB]", None),
        ("-n3v[TAB]", None),
        ("-n-3v[TAB]", None),
        ("-n3v [TAB]", None),
        ("-n-3v [TAB]", None),
        ("-vn3v [TAB]", None),
        ("-vn3v[TAB]", None),
        ("-- [TAB]", Some(path.to_owned())),
        ("-- a[TAB]", Some(path.to_owned())),
        ("-x [TAB]", None),
        ("-vv [TAB]", None),
        ("-n 9 [TAB]", None),
        ("-n9 [TAB]", None),
        ("-n- [TAB]", None),
        ("-n-- [TAB]", None),
        ("--number=-[TAB]", None),
        ("-vnn3[TAB]", None),
        ("-n -3 [TAB]", None),
        ("-n -3 -[TAB]", None),
        ("--mode [TAB]", None),
        ("--mode fast [TAB]", None),
        ("--mode=fast [TAB]", None),
        ("-n3 [TAB]", None),
        ("-n-3 -- [TAB]", Some(path.to_owned())),
        ("-n-3 -- a[TAB]", Some(path.to_owned())),
        ("-n-3 -- -[TAB]", Some(path.to_owned())),
        ("-n-3 -- --m[TAB]", Some(path.to_owned())),
        ("-n -v [TAB]", None),
        ("-n --mode [TAB]", None),
        ("-n -9[TAB]", None),
        ("-n -[TAB]", None),
        ("--mode j[TAB]", None),
        ("--mode junk [TAB]", None),
        ("-n9[TAB]", None),
        ("--number=9 [TAB]", None),
        ("-3 [TAB]", None),
    ];
    for (input, dir) in cases {
        println!("CASE: {input:?} => {}", run(input, dir.as_deref()));
    }
}

