-vn-3
-vn-2
-vn-1
-vn0
-vn1
-vn2
-vn3
"#]]
    );

    // The `-` prefix narrows the set to the three negative integers, across
    // the short attached, `=` and long spellings.
    assert_data_eq!(
        complete!(cluster_command(), "-n-[TAB]"),
        snapbox::str![[r#"
-n-3
-n-2
-n-1
"#]]
