#![cfg(feature = "unstable-dynamic")]
use clap::Command;
fn cmp(line: &str, hyphen: bool, neg: bool) {
    let mut pos = clap::Arg::new("p").value_parser(["-3", "3", "x"]);
    if hyphen { pos = pos.allow_hyphen_values(true); }
    if neg { pos = pos.allow_negative_numbers(true); }
    let cmd = Command::new("t").arg(pos)
        .arg(clap::Arg::new("n").short('n').value_parser(["-3","3"]));
    let raw: Vec<&str> = std::iter::once("t").chain(line.split_whitespace()).collect();
    let parser = cmd.clone().try_get_matches_from(raw).map(|m|
        format!("OK p={:?} n={:?}", m.get_one::<String>("p").map(String::as_str), m.get_one::<String>("n").map(String::as_str)))
        .map_err(|e| format!("ERR({})", e.kind()));

    let mut args: Vec<std::ffi::OsString> = std::iter::once("t").chain(line.split_whitespace()).map(std::ffi::OsString::from).collect();
    args.push("".into());
    let idx = args.len()-1;
    let comp = clap_complete::engine::complete(&mut cmd.clone(), args, idx, None)
        .map(|cs| format!("OK n={}", cs.len()))
        .unwrap_or_else(|e| format!("ERR({e})"));
    let align = match (&parser, &comp) {
        (Ok(_), Ok(_)) => "ALIGNED",
        (Err(_), Err(_)) => "ALIGNED",
        _ => "*** MISMATCH",
