cat > clap_complete/tests/testsuite/probe.rs <<'EOF'
#![cfg(feature = "unstable-dynamic")]
fn tool() -> clap::Command {
    clap::Command::new("tool")
        .arg(clap::Arg::new("verbose").short('v').long("verbose").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("number").short('n').long("number").value_parser(["-3","-2","-1","0","1","2","3"]))
        .arg(clap::Arg::new("mode").long("mode").value_parser(["fast","safe"]))
        .arg(clap::Arg::new("path").value_hint(clap::ValueHint::DirPath))
}
fn run(input: &str) -> String {
    let mut args = vec![std::ffi::OsString::from("tool")];
    let (prior, _) = input.split_once("[TAB]").unwrap();
    args.extend(prior.split_whitespace().map(std::ffi::OsString::from));
    if prior.ends_with(char::is_whitespace) { args.push(std::ffi::OsString::default()); }
    let i = args.len()-1;
    match clap_complete::engine::complete(&mut tool(), args, i, None) {
        Ok(cs) => format!("OK {}", cs.into_iter().map(|c| c.get_value().to_str().unwrap().to_owned()).collect::<Vec<_>>().join(",")),
        Err(e) => format!("ERR:{e}"),
    }
}
#[test]
fn p() {
    for input in [
        "-n path [TAB]", "-n foo [TAB]", "-n 3 path [TAB]", "-n3 path [TAB]",
        "path -n3 [TAB]", "-n-3 path [TAB]",
        "-n -3 path [TAB]", "--mode fast path [TAB]",
    ] { println!("{input:?} => {}", run(input)); }
}
EOF
