+fn pos_accepts_negative_number(cmd: &clap::Command, pos_index: usize) -> bool {
+    cmd.get_positionals()
+        .find(|a| a.get_index() == Some(pos_index))
+        .map(|p| p.is_allow_negative_numbers_set())
+        .unwrap_or(false)
+}
